using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Xml.Serialization;
using System.Windows.Forms;
using System.Drawing;
namespace JingFamily {
 public class FamilyEntry { public string Id="",Name="",Created="",LastOpened=""; }
 public class RemovedFamily {public FamilyEntry Entry=new FamilyEntry();public string TrashId="",RemovedAt="";public bool Purging=false;}
 public class FamilyIndex {public int Version=2;public string ActiveId="";public List<FamilyEntry> Families=new List<FamilyEntry>();public List<RemovedFamily> Trash=new List<RemovedFamily>();}
 public class FamilySummary {public FamilyEntry Entry;public string Title="",Status="正常";public int People,Events,Documents,Tasks;}
 public static class Library {
  public static string BaseRoot="";public static FamilyIndex Index=new FamilyIndex();public static bool Ready=false;
  public static string IndexPath {get{return Path.Combine(BaseRoot,"library.xml");}}
  static string Stamp(){return DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");}
  static bool GuidId(string id){Guid value;return Guid.TryParseExact(id,"N",out value);}
  public static string Child(string folder,string id){if(!GuidId(id))throw new Exception("家谱管理编号无效。");string parent=Path.GetFullPath(Path.Combine(BaseRoot,folder));string path=Path.GetFullPath(Path.Combine(parent,id));if(!path.StartsWith(parent+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("家谱目录超出范围。");NoLink(parent);NoLink(path);return path;}
  static void NoLink(string path){if((Directory.Exists(path)||File.Exists(path))&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new Exception("家谱管理目录不能使用符号链接或目录联接："+path);}
  public static string RootFor(string id){if(id=="legacy")return BaseRoot;return Child("families",id);}
  static string NameValue(string name){name=(name??"").Trim();if(name.Length==0||name.Length>100)throw new Exception("家谱名称须为 1～100 个字符。");return name;}
  static T ReadXml<T>(string path){var cfg=new System.Xml.XmlReaderSettings{DtdProcessing=System.Xml.DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=50L*1024*1024};using(var r=System.Xml.XmlReader.Create(path,cfg))return (T)new XmlSerializer(typeof(T)).Deserialize(r);}
  static void WriteIndex(){Index.Version=2;string temp=IndexPath+".tmp";using(var f=File.Create(temp))new XmlSerializer(typeof(FamilyIndex)).Serialize(f,Index);if(File.Exists(IndexPath))File.Replace(temp,IndexPath,IndexPath+".previous");else File.Move(temp,IndexPath);}
  static FamilyEntry Entry(string id){var e=Index.Families.Find(x=>x.Id==id);if(e==null)throw new Exception("找不到该家谱。");return e;}
  public static FamilyData ReadFamily(string id){Entry(id);string file=Path.Combine(RootFor(id),"family.xml");NoLink(file);if(!File.Exists(file))throw new Exception("家谱数据文件缺失，请从备份恢复："+file);var data=Store.Deserialize(File.ReadAllBytes(file));Store.Validate(data);return data;}
  public static void Initialize(string root){Ready=false;BaseRoot=Path.GetFullPath(root);Directory.CreateDirectory(BaseRoot);NoLink(BaseRoot);NoLink(IndexPath);if(File.Exists(IndexPath)){Index=ReadXml<FamilyIndex>(IndexPath);if(Index==null||(Index.Version!=1&&Index.Version!=2)||Index.Families==null||Index.Trash==null||Index.Families.Count==0)throw new Exception("多家谱目录索引不完整，请检查 library.xml.previous。");var ids=new HashSet<string>();foreach(var e in Index.Families)if(e==null||(e.Id!="legacy"&&!GuidId(e.Id))||!ids.Add(e.Id))throw new Exception("家谱索引编号重复或无效。");foreach(var t in Index.Trash)if(t==null||t.Entry==null||!GuidId(t.TrashId)||(t.Entry.Id!="legacy"&&!GuidId(t.Entry.Id)))throw new Exception("回收区索引无效。");if(!ids.Contains(Index.ActiveId))throw new Exception("当前家谱索引无效。");}else{Index=new FamilyIndex();if(File.Exists(Path.Combine(BaseRoot,"family.xml"))){var d=Store.Deserialize(File.ReadAllBytes(Path.Combine(BaseRoot,"family.xml")));Store.Validate(d);Index.Families.Add(new FamilyEntry{Id="legacy",Name=d.Title,Created=Stamp()});Index.ActiveId="legacy";WriteIndex();}else{var e=CreateInternal(new FamilyData(),"我的家谱");Index.ActiveId=e.Id;WriteIndex();}}Ready=true;Open(Index.ActiveId);}
  public static void Open(string id){var data=ReadFamily(id);string mediaRoot=Path.Combine(RootFor(id),"media");NoLink(mediaRoot);Directory.CreateDirectory(mediaRoot);var e=Entry(id);string oldActive=Index.ActiveId,oldOpened=e.LastOpened;Index.ActiveId=id;e.LastOpened=Stamp();try{WriteIndex();}catch{Index.ActiveId=oldActive;e.LastOpened=oldOpened;throw;}Store.Root=RootFor(id);Store.Data=data;}
  public static List<FamilySummary> Summaries(){var list=new List<FamilySummary>();foreach(var e in Index.Families){var s=new FamilySummary{Entry=e,Title=e.Name};try{var d=Ready&&e.Id==Index.ActiveId?Store.Data:ReadFamily(e.Id);s.Title=String.IsNullOrWhiteSpace(d.Title)?"未命名家谱":d.Title;s.People=d.People.Count;s.Events=d.Events.Count;s.Documents=d.Documents.Count;s.Tasks=d.Tasks.Count(x=>!x.Done);}catch(Exception ex){s.Status="读取失败："+ex.GetBaseException().Message;}list.Add(s);}return list;}
  static FamilyEntry CreateInternal(FamilyData data,string name,Dictionary<string,byte[]> media=null,string copyRoot=null){name=NameValue(name);data=Store.Deserialize(Store.Serialize(data));data.Title=name;Store.Validate(data);string id=Guid.NewGuid().ToString("N");string stage=Child("staging",id),target=Child("families",id);Directory.CreateDirectory(Path.Combine(stage,"media"));var files=data.People.Select(p=>p.Portrait).Concat(data.Documents.Select(d=>d.File)).Where(f=>f!="").Distinct();foreach(string f in files){Store.CheckMedia(f);string dest=Path.Combine(stage,f);if(media!=null){if(!media.ContainsKey(f))throw new Exception("备份缺少附件："+f);File.WriteAllBytes(dest,media[f]);}else if(copyRoot!=null){NoLink(Path.Combine(copyRoot,"media"));string source=Path.Combine(copyRoot,f);NoLink(source);if(!File.Exists(source))throw new Exception("原家谱附件缺失："+f);File.Copy(source,dest);}else throw new Exception("新家谱缺少附件来源。");}File.WriteAllBytes(Path.Combine(stage,"family.xml"),Store.Serialize(data));Directory.CreateDirectory(Path.Combine(BaseRoot,"families"));Directory.Move(stage,target);var entry=new FamilyEntry{Id=id,Name=name,Created=Stamp()};Index.Families.Add(entry);try{if(Index.ActiveId=="")Index.ActiveId=id;WriteIndex();}catch{Index.Families.Remove(entry);Directory.Move(target,stage);throw;}return entry;}
  public static FamilyEntry Create(string name){return CreateInternal(new FamilyData(),name);}
  public static FamilyEntry CreateData(FamilyData data,string name){return CreateInternal(data,name);}
  public static FamilyEntry Copy(string id,string name){return CreateInternal(ReadFamily(id),name,null,RootFor(id));}
  public static FamilyEntry ImportBackup(string path,string name){Dictionary<string,byte[]> files;var d=Store.ReadBackup(path,out files);return CreateInternal(d,name,files);}
  public static void Rename(string id,string name){name=NameValue(name);var e=Entry(id);var d=ReadFamily(id);d.Title=name;string root=RootFor(id);if(id==Index.ActiveId)Store.Commit(d);else{string file=Path.Combine(root,"family.xml"),temp=file+".tmp";File.WriteAllBytes(temp,Store.Serialize(d));File.Replace(temp,file,file+".previous");}e.Name=name;WriteIndex();}
  public static void Export(string id,string path){var data=ReadFamily(id);Store.BackupAt(path,data,RootFor(id));}
  public static void Remove(string id){if(Index.Families.Count<=1)throw new Exception("至少保留一份家谱。请先新建或恢复另一份家谱，再移除此家谱。");var entry=Entry(id);var data=ReadFamily(id);entry.Name=String.IsNullOrWhiteSpace(data.Title)?"未命名家谱":data.Title;string next=Index.ActiveId==id?Index.Families.First(x=>x.Id!=id).Id:Index.ActiveId;var nextData=ReadFamily(next);string trashId=Guid.NewGuid().ToString("N"),dest=Child("trash",trashId),source=RootFor(id);Directory.CreateDirectory(Path.Combine(BaseRoot,"trash"));var moved=new List<string>();try{if(id=="legacy"){Directory.CreateDirectory(dest);foreach(string item in new[]{"family.xml","family.xml.previous","media","backups"}){string from=Path.Combine(source,item),to=Path.Combine(dest,item);NoLink(from);if(File.Exists(from)){File.Move(from,to);moved.Add(item);}else if(Directory.Exists(from)){Directory.Move(from,to);moved.Add(item);}}}else Directory.Move(source,dest);var removed=new RemovedFamily{Entry=entry,TrashId=trashId,RemovedAt=Stamp()};int position=Index.Families.IndexOf(entry);string old=Index.ActiveId;Index.Families.Remove(entry);Index.Trash.Add(removed);Index.ActiveId=next;try{WriteIndex();}catch{Index.Families.Insert(position,entry);Index.Trash.Remove(removed);Index.ActiveId=old;throw;}}catch{if(id=="legacy"){foreach(string item in moved){string from=Path.Combine(dest,item),to=Path.Combine(source,item);if(File.Exists(from))File.Move(from,to);else if(Directory.Exists(from))Directory.Move(from,to);}}else if(Directory.Exists(dest)&&!Directory.Exists(source))Directory.Move(dest,source);throw;}Store.Root=RootFor(next);Store.Data=nextData;}
  public static FamilyEntry Restore(string trashId){var removed=Index.Trash.Find(x=>x.TrashId==trashId);if(removed==null)throw new Exception("回收区记录不存在。");if(removed.Purging)throw new Exception("该家谱已有永久删除操作，不能恢复残余文件；请重试永久删除。");string source=Child("trash",trashId);if(!File.Exists(Path.Combine(source,"family.xml")))throw new Exception("回收区数据文件缺失。");var data=Store.Deserialize(File.ReadAllBytes(Path.Combine(source,"family.xml")));Store.Validate(data);string id=removed.Entry.Id;if(id=="legacy"||Index.Families.Any(x=>x.Id==id))id=Guid.NewGuid().ToString("N");string target=Child("families",id);if(Directory.Exists(target))throw new Exception("目标目录已存在，未覆盖原文件。");Directory.CreateDirectory(Path.Combine(BaseRoot,"families"));Directory.Move(source,target);var entry=new FamilyEntry{Id=id,Name=data.Title,Created=removed.Entry.Created,LastOpened=removed.Entry.LastOpened};Index.Families.Add(entry);Index.Trash.Remove(removed);try{WriteIndex();}catch{Index.Families.Remove(entry);Index.Trash.Add(removed);Directory.Move(target,source);throw;}return entry;}
  static void CheckPurgePath(string path,string root){string full=Path.GetFullPath(path),boundary=Path.GetFullPath(root);if(!String.Equals(full,boundary,StringComparison.OrdinalIgnoreCase)&&!full.StartsWith(boundary+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("删除路径超出选中的回收区家谱目录。");string current=Directory.Exists(full)?full:Path.GetDirectoryName(full);NoLink(full);while(current!=null&&current.Length>=boundary.Length){NoLink(current);if(String.Equals(current,boundary,StringComparison.OrdinalIgnoreCase))break;current=Path.GetDirectoryName(current);}}
  static Tuple<List<string>,List<string>> PurgePlan(string root){NoLink(root);if(File.Exists(root))throw new Exception("回收区目录被其他文件占用，未删除。");var files=new List<string>();var dirs=new List<string>();if(!Directory.Exists(root))return Tuple.Create(files,dirs);var pending=new Stack<string>();pending.Push(root);while(pending.Count>0){string dir=pending.Pop();CheckPurgePath(dir,root);dirs.Add(dir);foreach(string f in Directory.GetFiles(dir)){CheckPurgePath(f,root);files.Add(f);}foreach(string d in Directory.GetDirectories(dir)){CheckPurgePath(d,root);pending.Push(d);}}return Tuple.Create(files,dirs);}
  public static void PermanentlyDelete(string trashId,string typedName){var removed=Index.Trash.Find(x=>x.TrashId==trashId);if(removed==null)throw new Exception("该家谱不在回收区，未删除。");if(!String.Equals(typedName,String.IsNullOrWhiteSpace(removed.Entry.Name)?"未命名家谱":removed.Entry.Name,StringComparison.Ordinal))throw new Exception("输入的家谱名称不匹配，未删除。");string root=Child("trash",trashId);var plan=PurgePlan(root);bool old=removed.Purging;removed.Purging=true;try{WriteIndex();}catch{removed.Purging=old;throw;}try{foreach(string file in plan.Item1){CheckPurgePath(file,root);if(File.Exists(file)){var attributes=File.GetAttributes(file);if((attributes&FileAttributes.ReadOnly)!=0)File.SetAttributes(file,attributes&~FileAttributes.ReadOnly);File.Delete(file);}}foreach(string directory in plan.Item2.OrderByDescending(x=>x.Length)){CheckPurgePath(directory,root);if(Directory.Exists(directory))Directory.Delete(directory,false);}int pos=Index.Trash.IndexOf(removed);Index.Trash.Remove(removed);try{WriteIndex();}catch{Index.Trash.Insert(pos,removed);throw;}}catch(Exception ex){throw new Exception("永久删除未全部完成。该家谱已标记为「未完成删除」，请关闭占用文件的程序后重试删除；不要将残余内容作为完整家谱恢复。\n"+ex.GetBaseException().Message,ex);}}
  public static void EmptyTrash(string confirmation){if(confirmation!="永久清空回收区")throw new Exception("确认文字不匹配，未清空。");var items=Index.Trash.ToArray();foreach(var item in items)PurgePlan(Child("trash",item.TrashId));int done=0;try{foreach(var item in items){PermanentlyDelete(item.TrashId,String.IsNullOrWhiteSpace(item.Entry.Name)?"未命名家谱":item.Entry.Name);done++;}}catch(Exception ex){throw new Exception("已永久删除 "+done+" 份，还有 "+Index.Trash.Count+" 份待处理。\n"+ex.Message,ex);}}
 }
 public class NameEditor:Editor {TextBox name;public string Value="";public NameEditor(string title,string value):base(title,620,300){name=TextField("家谱名称 *",value);Field("说明",Ui.Label("每份家谱的成员、附件、待办及备份相互独立。",9),45);}protected override bool Commit(){Value=name.Text.Trim();if(Value.Length==0||Value.Length>100)throw new Exception("名称须为 1～100 个字符。");return true;}}
 public class LibraryPanel:UserControl {
  Action changed;TabControl tabs;TextBox search;DataGridView grid;
  public LibraryPanel(Action afterChange){changed=afterChange;Dock=DockStyle.Fill;Font=Ui.Font();BackColor=Ui.Cream;tabs=new PillTabs{Dock=DockStyle.Fill};Controls.Add(tabs);RefreshList();}
  string Key(DataGridView g){return g.CurrentRow==null?"":g.CurrentRow.Tag as string??"";}
  string Ask(string title,string value){using(var d=new NameEditor(title,value))return d.ShowDialog(this)==DialogResult.OK?d.Value:null;}
  void Complete(){changed();}
  void RefreshList(){foreach(TabPage page in tabs.TabPages.Cast<TabPage>().ToArray())page.Dispose();tabs.TabPages.Clear();var live=new TabPage("全部家谱"){Padding=new Padding(8),BackColor=Ui.Cream};tabs.TabPages.Add(live);var tools=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true,Padding=new Padding(0,6,0,0)};search=new TextBox{Width=180,Margin=new Padding(0,5,9,0)};tools.Controls.Add(Ui.Button("新建家谱",()=>{string n=Ask("新建家谱", "我的新家谱");if(n!=null){var e=Library.Create(n);Library.Open(e.Id);Complete();}},true));tools.Controls.Add(Ui.Button("打开 / 切换",()=>{if(Key(grid)!=""){Library.Open(Key(grid));Complete();}},true));tools.Controls.Add(Ui.Button("重命名",()=>{if(Key(grid)=="")return;string n=Ask("重命名家谱",Library.ReadFamily(Key(grid)).Title);if(n!=null){Library.Rename(Key(grid),n);Complete();}}));tools.Controls.Add(Ui.Button("复制",()=>{if(Key(grid)=="")return;string n=Ask("复制家谱",Library.ReadFamily(Key(grid)).Title+" · 副本");if(n!=null){var e=Library.Copy(Key(grid),n);Library.Open(e.Id);Complete();}}));tools.Controls.Add(Ui.Button("从 ZIP 新增",()=>{string f=Ui.OpenPath("完整家谱备份|*.zip");if(f==null)return;string n=Ask("从备份新增家谱",Path.GetFileNameWithoutExtension(f));if(n!=null){var e=Library.ImportBackup(f,n);Library.Open(e.Id);Complete();}}));tools.Controls.Add(Ui.Button("备份选中",()=>{if(Key(grid)=="")return;string f=Ui.SavePath("完整家谱备份|*.zip",Library.ReadFamily(Key(grid)).Title+".zip");if(f!=null){Library.Export(Key(grid),f);Ui.Info("已保存该家谱的完整备份。");}}));tools.Controls.Add(Ui.Button("移入回收区",()=>{if(Key(grid)=="")return;if(Ui.Confirm("将选中家谱移入回收区？\n可在回收区恢复，其他家谱不会被修改。")){Library.Remove(Key(grid));Complete();}}));tools.Controls.Add(Ui.Button("打开总目录",()=>Ui.Open(Library.BaseRoot)));tools.Controls.Add(Ui.Label("搜索家谱：",9));tools.Controls.Add(new InputFrame(search){Width=210,Height=39,Margin=new Padding(0,0,10,8)});live.Controls.Add(tools);grid=Ui.Grid();Ui.Columns(grid,"当前","家谱名称","成员","事件","资料","未完成待办","最近打开","编号","状态");grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.None;grid.Columns[0].Width=70;grid.Columns[1].AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill;grid.Columns[1].MinimumWidth=170;grid.Columns[1].FillWeight=180;for(int i=2;i<=4;i++)grid.Columns[i].Width=55;grid.Columns[5].Width=95;grid.Columns[6].Width=170;grid.Columns[7].Width=80;grid.Columns[8].AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill;grid.Columns[8].MinimumWidth=120;live.Controls.Add(grid);grid.BringToFront();search.TextChanged+=(s,e)=>LoadRows();grid.CellDoubleClick+=(s,e)=>{if(e.RowIndex>=0)try{Library.Open(Key(grid));Complete();}catch(Exception ex){Ui.Error(ex);}};LoadRows();var trash=new TabPage("回收区"){Padding=new Padding(8),BackColor=Ui.Cream};tabs.TabPages.Add(trash);var deleted=Ui.Grid();Ui.Columns(deleted,"家谱名称","移入时间","原编号","状态");foreach(var t in Library.Index.Trash){int r=deleted.Rows.Add(t.Entry.Name,t.RemovedAt,t.Entry.Id=="legacy"?"原家谱":t.Entry.Id.Substring(0,6),t.Purging?"未完成删除":"可恢复");deleted.Rows[r].Tag=t.TrashId;}var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true,Padding=new Padding(0,8,0,0)};bar.Controls.Add(Ui.Button("恢复选中家谱",()=>{if(Key(deleted)!=""){Library.Restore(Key(deleted));Complete();}},true));bar.Controls.Add(Ui.Danger("永久删除选中",()=>{var t=Library.Index.Trash.Find(x=>x.TrashId==Key(deleted));if(t==null){Ui.Info("请先选择回收区中的一份家谱。");return;}using(var dialog=new PurgeConfirmation(String.IsNullOrWhiteSpace(t.Entry.Name)?"未命名家谱":t.Entry.Name,false,1))if(dialog.ShowDialog(this)==DialogResult.OK){try{Library.PermanentlyDelete(t.TrashId,dialog.Confirmation);Ui.Info("该家谱及其回收区文件已永久删除。");}finally{Complete();}}}));bar.Controls.Add(Ui.Danger("清空回收区",()=>{if(Library.Index.Trash.Count==0){Ui.Info("回收区已经为空。");return;}using(var dialog=new PurgeConfirmation("",true,Library.Index.Trash.Count))if(dialog.ShowDialog(this)==DialogResult.OK){try{Library.EmptyTrash(dialog.Confirmation);Ui.Info("回收区已清空。");}finally{Complete();}}}));bar.Controls.Add(Ui.Label("永久删除无法从本软件恢复，请先保存所需备份。",9));trash.Controls.Add(bar);trash.Controls.Add(deleted);deleted.BringToFront();}
  void LoadRows(){grid.Rows.Clear();foreach(var s in Library.Summaries().Where(x=>x.Title.IndexOf(search.Text.Trim(),StringComparison.CurrentCultureIgnoreCase)>=0)){int r=grid.Rows.Add(s.Entry.Id==Library.Index.ActiveId?"使用中":"",s.Title,s.People,s.Events,s.Documents,s.Tasks,s.Entry.LastOpened,s.Entry.Id=="legacy"?"原家谱":s.Entry.Id.Substring(0,6),s.Status);grid.Rows[r].Tag=s.Entry.Id;}}
 }
}
